"""Self-contained explorer UI; no network/CDN dependencies."""
HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Genome QC Explorer</title>
<style>
:root{color-scheme:light;--ink:#213343;--blue:#245d79;--line:#d7e0e5;--muted:#566b78}*{box-sizing:border-box}body{font:15px/1.5 system-ui,sans-serif;margin:0;background:#f5f7f8;color:var(--ink)}header{padding:24px 4%;background:white;border-bottom:1px solid var(--line)}h1,h2,h3,p{margin:0 0 12px}header p{color:var(--muted)}main{max-width:1500px;margin:auto;padding:24px 4%}nav{display:flex;gap:8px}button,input,select{font:inherit;padding:8px;border:1px solid var(--line);border-radius:5px;background:white;color:var(--ink)}button{cursor:pointer}button:hover,button[aria-selected=true]{background:#e3eef4;border-color:var(--blue)}button:disabled{opacity:.45;cursor:default}a{color:var(--blue)}label{display:inline-flex;flex-direction:column;gap:4px;font-size:13px}section,.panel{background:white;border:1px solid var(--line);padding:20px;border-radius:8px;margin-bottom:18px}.cards,.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.card{padding:16px;background:#edf3f5;border-radius:6px}.card{text-align:left}.card small{display:block;margin-top:8px;color:var(--blue)}.card strong{display:block;font-size:26px}.figure{border:1px solid var(--line);padding:12px;border-radius:6px}.figure img{width:100%;height:200px;object-fit:contain}.figure button{width:100%;padding:0;border:0}.figure p{font-size:13px}.toolbar,.rule{display:flex;flex-wrap:wrap;align-items:end;gap:10px;margin:12px 0}#tables{max-width:650px}#rules input{max-width:160px}#columns{display:flex;flex-wrap:wrap;gap:12px;max-height:180px;overflow:auto}#columns label{flex-direction:row;align-items:center}#grid{overflow:auto;max-height:65vh;border:1px solid var(--line)}table{border-collapse:separate;border-spacing:0;font-size:13px;min-width:100%}th,td{padding:8px 10px;border-bottom:1px solid var(--line);white-space:nowrap;text-align:left}th{position:sticky;top:0;background:#eaf0f3;z-index:1}th button{padding:0;border:0;background:none;font-weight:600}tr:hover td{background:#f0f6f8}.muted{color:var(--muted);font-size:13px}.notice{padding:10px;background:#edf3f5;border-left:3px solid var(--blue)}#error{color:#8d2525;white-space:pre-wrap}dialog{width:min(95vw,1300px);max-height:95vh;border:1px solid var(--line);border-radius:8px}dialog::backdrop{background:#182a38aa}dialog img{width:100%;height:auto}dialog .toolbar{position:sticky;top:0;background:white}details{margin:12px 0}summary{cursor:pointer}footer{margin-top:24px;color:var(--muted)}[hidden]{display:none!important}
</style></head><body>
<header><h1>Genome QC Explorer</h1><p>Review the atlas, select genomes, and export the results you need.</p><nav aria-label="Explorer views"><button id="summaryTab" aria-selected="true">Summary &amp; atlas</button><button id="exploreTab" aria-selected="false">Explore tables</button><button id="selectionTab" aria-selected="false">Select genomes</button></nav></header>
<main><p id="error" role="alert"></p>
<div id="summaryView"><section><h2>Run summary</h2><div id="cards" class="cards"></div><p id="runDetails" class="muted"></p><button id="start">Explore genome quality</button></section>
<section><h2>Genome atlas</h2><p class="muted">These figures summarize the original analysis. Table filters do not recalculate the figures. Select a preview to enlarge it; PDF links open the full figure.</p><div id="gallery" class="gallery"></div><details><summary>Other figures and reports</summary><ul id="otherFigures"></ul></details></section></div>
<div id="selectionView" hidden><section><h2>Select genomes</h2><p>Start with every assessed genome. Add inclusive quality ranges or exact taxonomy filters below. All criteria combine with AND; active numeric filters exclude missing values. This changes your selection only, never the original results or atlas.</p><p class="muted">The saved criteria include the indexed source-table SHA-256, tool version, timestamp, and selected genome IDs. Reloading verifies both the data and membership.</p><div class="toolbar"><button id="saveRecipe">Download selection record</button><label>Reload selection record<input id="loadRecipe" type="file" accept=".json"></label><button id="saveIDs">Download genome IDs</button></div><p id="selectionStatus" role="status"></p><div id="selectionWorkspace"></div></section></div><div id="exploreView" hidden><section><h2>Explore results</h2><div class="toolbar"><label>Find a table<input id="tableSearch" placeholder="atlas, CheckM, taxonomy…"></label><label>Result table<select id="tables"></select></label><label>Genome ID<select id="genome"><option value="">All genomes</option></select></label></div>
<div class="toolbar"><label>Search all columns<input id="query" placeholder="Text to find"></label><button id="addRule">Add column filter</button><button id="apply">Apply filters</button><button id="reset">Reset filters</button></div>
<p class="muted">Filters combine with AND. Numeric bounds are inclusive and exclude missing/non-numeric values. Taxonomy values match exactly. Click a column heading to sort.</p><div id="rules"></div>
<div class="toolbar"><button id="setCohort">Use matching genomes across tables</button><button id="clearCohort" hidden>Clear genome subset</button></div><p id="cohortNote" class="notice" hidden></p>
<details><summary>Choose columns for display and export</summary><div class="toolbar"><button id="allColumns">All columns</button></div><div id="columns"></div></details>
<div class="toolbar"><button id="prev">Previous</button><button id="next">Next</button><a id="export">Download filtered CSV</a><button id="saveFilters">Save selection settings</button></div><p id="status" aria-live="polite"></p><div id="grid"></div></section></div>
<footer id="footer"></footer></main>
<dialog id="figureDialog"><div class="toolbar"><strong id="figureTitle"></strong><a id="figurePDF" target="_blank" rel="noopener">Open PDF</a><button id="closeFigure">Close</button></div><img id="figureImage" alt="Expanded atlas figure"></dialog>
<script>
const el=id=>document.getElementById(id);let activeView='summary';let page=0,catalog=[],fields=[],sort='',direction='asc',cohort=null,cohortLabel='',requestID=0;
const make=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n};
async function api(path){const r=await fetch(path);if(!r.ok){const t=await r.text();throw Error('Request failed ('+r.status+'): '+t.replace(/<[^>]*>/g,' ').trim())}return r.json()}
function action(fn){return async()=>{try{el('error').textContent='';await fn()}catch(e){el('error').textContent=e.message}}}
function show(view){activeView=view;for(const v of ['summary','explore','selection']){el(v+'View').hidden=view!==v;el(v+'Tab').setAttribute('aria-selected',view===v)}const panel=el('grid').closest('section');(view==='selection'?el('selectionWorkspace'):el('exploreView')).append(panel);el('tableSearch').parentElement.hidden=view==='selection';el('tables').parentElement.hidden=view==='selection';el('genome').parentElement.hidden=view==='selection';el('saveFilters').hidden=view==='selection';el('setCohort').hidden=view==='selection';panel.querySelector('h2').textContent=view==='selection'?'Selection criteria and matching genomes':'Explore results'}

function rules(){return [...el('rules').children].map(row=>{const op=row.querySelector('.op').value;const rule={column:row.querySelector('.field').value,op};if(op==='range'){rule.min=row.querySelector('.min').value;rule.max=row.querySelector('.max').value}else rule.value=row.querySelector('.value')?.value||'';return rule})}
function selected(){return [...el('columns').querySelectorAll('input:checked')].map(c=>c.value)}
function params(){const p=new URLSearchParams({table:el('tables').value,q:el('query').value,page,genome:el('genome').value,filters:JSON.stringify(rules()),sort,direction,columns:JSON.stringify(selected())});if(cohort)p.set('cohort',JSON.stringify(cohort));return p}
async function load(){const id=++requestID,p=params();el('status').textContent='Loading…';el('export').removeAttribute('href');const d=await api('/api/rows?'+p);if(id!==requestID)return;el('export').href='/api/export?'+p;el('status').textContent=d.total.toLocaleString()+' matching rows · '+d.columns.length+' columns · page '+(page+1)+' of '+Math.max(1,Math.ceil(d.total/100));el('prev').disabled=page===0;el('next').disabled=(page+1)*100>=d.total;const t=make('table'),head=t.createTHead().insertRow();for(const c of d.columns){const th=make('th'),b=make('button',c+(sort===c?(direction==='asc'?' ↑':' ↓'):''));b.onclick=action(async()=>{direction=sort===c&&direction==='asc'?'desc':'asc';sort=c;page=0;await load()});th.append(b);head.append(th)}const body=t.createTBody();for(const row of d.rows){const tr=body.insertRow();for(const v of row)tr.insertCell().textContent=v??''}el('grid').replaceChildren(t)}
async function tableChanged(){page=0;sort='';el('query').value='';el('rules').replaceChildren();fields=await api('/api/schema?table='+el('tables').value);el('columns').replaceChildren();for(const f of fields){const l=make('label'),i=make('input');i.type='checkbox';i.checked=true;i.value=f.name;i.onchange=action(async()=>{page=0;await load()});l.append(i,document.createTextNode(f.name));el('columns').append(l)}await load()}
function addRule(){const row=make('div');row.className='rule';const field=make('select');field.className='field';field.setAttribute('aria-label','Filter column');for(const f of fields){const o=make('option',f.name);o.value=f.name;field.append(o)}const op=make('select');op.className='op';op.setAttribute('aria-label','Filter operation');const inputs=make('span');function values(){inputs.replaceChildren();const f=fields.find(f=>f.name===field.value);if(op.value==='range'){for(const [cls,hint] of [['min','Minimum'],['max','Maximum']]){const i=make('input');i.type='number';i.step='any';i.className=cls;i.placeholder=hint;i.setAttribute('aria-label',hint);inputs.append(i)}const hint=make('small',' Observed: '+f.minimum+' to '+f.maximum);inputs.append(hint)}else if(op.value!=='missing'){const i=make(op.value==='eq'&&f.choices.length?'select':'input');i.className='value';i.setAttribute('aria-label','Filter value');if(i.tagName==='SELECT'){for(const v of f.choices){const o=make('option',v);o.value=v;i.append(o)}}inputs.append(i)}}function options(){const f=fields.find(f=>f.name===field.value);op.replaceChildren();for(const [v,t] of (f.numeric?[['range','Between'],['eq','Equals'],['missing','Missing']]:[['eq','Equals'],['contains','Contains'],['missing','Missing']])){const o=make('option',t);o.value=v;op.append(o)}values()}field.onchange=options;op.onchange=values;const remove=make('button','Remove');remove.onclick=()=>row.remove();row.append(field,op,inputs,remove);el('rules').append(row);options()}
function tableOptions(){const current=el('tables').value,q=el('tableSearch').value.toLowerCase();el('tables').replaceChildren();for(const row of catalog.filter(r=>r.source.toLowerCase().includes(q))){const o=make('option',row.source+' ('+row.rows.toLocaleString()+' rows)');o.value=row.id;el('tables').append(o)}if([...el('tables').options].some(o=>o.value===current))el('tables').value=current;return current!==el('tables').value}
async function openSummarySubset(status,label){
 const inventory=catalog.find(t=>t.source==='Genome_inventory.tsv');
 if(status&&!inventory)throw Error('The genome inventory is unavailable for this output.');
 cohort=inventory?{table:inventory.id,q:'',filters:status?[{column:'status',op:'eq',value:status}]:[]}:null;
 cohortLabel=label;cohortMessage();
 el('tableSearch').value='';el('genome').value='';tableOptions();
 const master=catalog.find(t=>t.source==='Master_genome_QC.tsv');
 const preferred=(status.startsWith('assessed_')||(!status&&catalog.some(t=>t.source==='Selected_genome_QC.tsv')))?master:status==='not_assessed'?inventory:status==='included_in_atlas'?catalog.find(t=>t.source.endsWith('/genome_quality_annotated.tsv')):catalog.find(t=>t.source==='checkm/checkm_output.tsv');
 const target=preferred||inventory||catalog[0];
 if(!target)throw Error('No result tables are available.');
 el('tables').value=target.id;show('explore');await tableChanged();
}
function cohortMessage(){el('setCohort').disabled=!!cohort;el('clearCohort').hidden=!cohort;el('cohortNote').hidden=!cohort;el('cohortNote').textContent='Genome subset from '+cohortLabel+'. Only linked rows are shown in other tables; tables without genome links will be empty.'}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=make('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function openSelection(){const master=catalog.find(t=>t.source==='Master_genome_QC.tsv');if(!master)throw Error('No complete master table is available in this output.');cohort=null;cohortMessage();el('tableSearch').value='';tableOptions();el('tables').value=master.id;el('genome').value='';show('selection');await tableChanged();el('selectionStatus').textContent='All assessed genomes included until you add criteria.'}
async function receipt(){return api('/api/selection?'+new URLSearchParams({table:el('tables').value,filters:JSON.stringify(rules()),q:el('query').value}))}
el('selectionTab').onclick=action(openSelection);
el('saveRecipe').onclick=action(async()=>{const r=await receipt();await load();download(JSON.stringify(r,null,2),'genome-qc-selection.json','application/json');el('selectionStatus').textContent=r.genome_ids.length+' genomes recorded.'});
el('saveIDs').onclick=action(async()=>{const r=await receipt();await load();download('Genome_Id\n'+r.genome_ids.join('\n')+(r.genome_ids.length?'\n':''),'selected-genomes.tsv','text/tab-separated-values')});
el('loadRecipe').onchange=action(async()=>{const file=el('loadRecipe').files[0];if(!file)return;const r=JSON.parse(await file.text());if(r.format!=='genome-qc-selection'||r.schema_version!==1||!Array.isArray(r.filters)||!Array.isArray(r.genome_ids))throw Error('Unsupported selection record.');await openSelection();const current=await api('/api/selection?'+new URLSearchParams({table:el('tables').value,filters:JSON.stringify(r.filters),q:r.search||''}));if(current.indexed_table_sha256!==r.indexed_table_sha256||JSON.stringify(current.genome_ids)!==JSON.stringify(r.genome_ids))throw Error('Source data or selected genome IDs do not match this record; selection was not restored.');for(const rule of r.filters){addRule();const row=el('rules').lastElementChild;row.querySelector('.field').value=rule.column;row.querySelector('.field').onchange();row.querySelector('.op').value=rule.op;row.querySelector('.op').onchange();if(rule.op==='range'){row.querySelector('.min').value=rule.min??'';row.querySelector('.max').value=rule.max??''}else if(rule.op!=='missing')row.querySelector('.value').value=rule.value??''}el('query').value=r.search||'';await load();el('selectionStatus').textContent='Verified and restored '+current.genome_ids.length+' genomes.';el('loadRecipe').value=''});
el('summaryTab').onclick=()=>show('summary');el('exploreTab').onclick=()=>show('explore');el('start').onclick=()=>show('explore');el('addRule').onclick=addRule;el('tables').onchange=action(tableChanged);el('tableSearch').oninput=action(async()=>{if(tableOptions()&&el('tables').value)await tableChanged()});el('apply').onclick=action(async()=>{page=0;await load()});el('query').onkeydown=e=>{if(e.key==='Enter')el('apply').click()};el('genome').onchange=el('apply').onclick;el('reset').onclick=action(async()=>{el('rules').replaceChildren();el('query').value='';el('genome').value='';page=0;await load()});el('prev').onclick=action(async()=>{page=Math.max(0,page-1);await load()});el('next').onclick=action(async()=>{page++;await load()});el('allColumns').onclick=action(async()=>{el('columns').querySelectorAll('input').forEach(i=>i.checked=true);await load()});
el('setCohort').onclick=action(async()=>{if(el('genome').value)throw Error('Clear the single-genome selector before creating a cross-table subset.');const candidate={table:el('tables').value,q:el('query').value,filters:rules()};await api('/api/rows?'+new URLSearchParams({table:candidate.table,filters:JSON.stringify(candidate.filters),q:candidate.q}));cohort=candidate;cohortLabel=catalog.find(t=>t.id===cohort.table).source;cohortMessage();page=0;await load()});el('clearCohort').onclick=action(async()=>{cohort=null;cohortMessage();page=0;await load()});
el('saveFilters').onclick=action(async()=>{const data={table:catalog.find(t=>t.id===el('tables').value)?.source,filters:rules(),search:el('query').value,genome:el('genome').value,columns:selected(),sort,direction,cohort:cohort?{...cohort,source:cohortLabel}:null};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=make('a');a.href=url;a.download='genome-qc-selection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
el('closeFigure').onclick=()=>el('figureDialog').close();
action(async()=>{const [summary,tables,ids,files]=await Promise.all(['/api/summary','/api/tables','/api/genomes','/api/artifacts'].map(api));catalog=tables.sort((a,b)=>{const rank=x=>x.source.endsWith('/genome_quality_annotated.tsv')?0:x.source==='Genome_inventory.tsv'?1:x.source==='Master_genome_QC.tsv'?2:3;return rank(a)-rank(b)||a.source.localeCompare(b.source)});const labels={assessed_incomplete:'Incomplete assessments',assessed_selected:'Assessed · selected',assessed_not_selected:'Assessed · not selected',not_assessed:'Not assessed',included_in_atlas:'Included in atlas',excluded_after_rRNA_check:'Excluded after rRNA check',excluded_by_size_or_quality:'Excluded before rRNA check'};for(const [status,label,value] of [['','Input genomes',summary.genomes],...Object.entries(summary.counts).map(([k,v])=>[k,labels[k]||k,v])]){const c=make('button');c.type='button';c.className='card';c.dataset.status=status;c.setAttribute('aria-label',label+': '+value.toLocaleString()+'. Explore metrics');c.append(make('strong',value.toLocaleString()),make('span',label),make('small','View metrics →'));c.onclick=action(()=>openSummarySubset(status,label));el('cards').append(c)}el('runDetails').textContent='Genome QC '+summary.version+' · '+summary.status+' · '+summary.output;el('footer').textContent='Genome QC '+summary.version+' · Results are read-only. CSV exports include all matching rows, not just the current page.';for(const id of ids){const o=make('option',id);o.value=id;el('genome').append(o)}for(const f of files){if(f.path.startsWith('genome_quality_atlas/')&&f.path.endsWith('.png')){const pdf=files.find(x=>x.path===f.path.slice(0,-4)+'.pdf'),title=f.path.split('/').pop().replace(/\.png$/,'').replaceAll('_',' '),card=make('article');card.className='figure';const b=make('button'),img=make('img');img.src='/artifact?id='+f.id;img.alt=title;img.loading='lazy';b.append(img);b.onclick=()=>{el('figureTitle').textContent=title;el('figureImage').src=img.src;el('figureImage').alt=title;el('figurePDF').hidden=!pdf;if(pdf)el('figurePDF').href='/artifact?id='+pdf.id;el('figureDialog').showModal()};card.append(b,make('p',title));if(pdf){const a=make('a','Open PDF');a.href='/artifact?id='+pdf.id;a.target='_blank';a.rel='noopener';card.append(a)}el('gallery').append(card)}else if(!f.path.startsWith('genome_quality_atlas/')){const li=make('li'),a=make('a',f.path);a.href='/artifact?id='+f.id;a.target='_blank';a.rel='noopener';li.append(a);el('otherFigures').append(li)}}if(!el('gallery').children.length)el('gallery').append(make('p','No atlas previews were found in this output.'));tableOptions();if(catalog.length)await tableChanged()})()
</script></body></html>'''
